esbmc_test_source:
contract InvMutTest {
    C c;
    address creatorAddress;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function. We take a target address "to" and attempt to call migrateTo both as this contract
    // (which is the deployed InvMutTest, the caller for all calls to c) and we also declare a boolean flag simulateCreator
    // that if true, we will first try to detect whether this contract is the creator by attempting a migrateTo to address(this).
    // The general rule we assert: if this contract is NOT the creator then migrateTo(to) must revert; if it is the creator then migrateTo(to) may succeed.
    // We implement this by first trying migrateTo(to) and recording whether it reverted. Then we try to infer whether this contract is the creator by attempting migrateTo to self
    // in a try/catch: if migrateTo(address(this)) succeeds then this contract must be the creator; if it reverts then this contract is not the creator.

    function run(address to) public payable {
        // No preconditions on parameters.

        // First, try calling migrateTo(to) and record whether it reverted.
        bool migrateTo_reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            migrateTo_reverted = true;
        } else {
            migrateTo_reverted = false;
        }

        // Next, try calling migrateTo(address(this)) to detect whether this contract is the creator.
        bool migrateTo_self_reverted;
        c.migrateTo(address(this)); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            migrateTo_self_reverted = true;
        } else {
            migrateTo_self_reverted = false;
        }

        // General rule: if migrateTo_self_reverted == true (we are not creator) then migrateTo(to) must have reverted as well.
        // Equivalently: cannot have (not creator) and migrateTo(to) succeeded.
        assert(!(migrateTo_self_reverted && !migrateTo_reverted));
    }

    receive() external payable { }
}

